CREATE TABLE `actividades` (
  `id_actividad` int(11) NOT NULL,
  `id_dba` int(11) NOT NULL,
  `id_tipo` int(11) NOT NULL,
  `nombre` varchar(100) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `instrucciones` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Volcado de datos para la tabla `actividades`
--

INSERT INTO `actividades` (`id_actividad`, `id_dba`, `id_tipo`, `nombre`, `descripcion`, `instrucciones`) VALUES
(3, 1, 7, 'El Jardín de las Vocales', 'Reconocer visual y auditivamente las cinco vocales asociándolas a imágenes de su entorno.', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) El pictograma de la vocal aparece en el centro. 2) El niño escucha el sonido de la vocal (botón de audio repetible). 3) Debe arrastrar la imagen cuyo nombre empieza con esa vocal hasta la flor correspondiente. 4) Al soltar correctamente, la flor florece con animación suave.\nAdaptaciones TEA: Una sola instrucción por pantalla, leída en voz alta y con pictograma; máximo 5 elementos visibles a la vez; sin límite de tiempo en nivel fácil.\nNiveles: Fácil / Medio / Difícil (aumenta cantidad de vocales por ronda y quita el apoyo sonoro)\nTiempo estimado: 5-8 minutos\nRecompensa: Estrellas + insignia \'Jardinero de vocales\' al completar las 5 vocales'),
(4, 1, 4, 'Sonido y Figura', 'Identificar el sonido inicial de una palabra y relacionarlo con la imagen correcta.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se reproduce una palabra. 2) Aparecen imágenes con nombres de sonido inicial distinto. 3) El niño toca la imagen cuyo nombre comienza con el mismo sonido. 4) Confirmación inmediata.\nAdaptaciones TEA: Solo 3 opciones visibles; ícono de repetición de audio siempre disponible; sin distractores sonoros de fondo.\nNiveles: Fácil (2 opciones) / Medio (3 opciones) / Difícil (4 opciones con sonidos iniciales parecidos)\nTiempo estimado: 5-7 minutos\nRecompensa: Sellos de colores acumulables por ronda correcta'),
(5, 1, 1, 'Memo-Vocales', 'Asociar el grafema de cada vocal (mayúscula y minúscula) con su imagen representativa mediante un juego de memoria.', 'Mecánica: Memoria (parejas)\nCómo se juega: 1) El niño toca una carta y se voltea. 2) Toca una segunda carta. 3) Si coinciden (vocal-imagen), permanecen visibles con animación de brillo. 4) Si no coinciden, se voltean de nuevo tras 2 segundos.\nAdaptaciones TEA: Cuadrícula pequeña (máximo 12 cartas); resaltado visual de las cartas ya reveladas; sin límite de tiempo.\nNiveles: Fácil (6 pares, 2 volteos simultáneos permitidos) / Medio (8 pares) / Difícil (10 pares con mayúscula-minúscula mezcladas)\nTiempo estimado: 6-10 minutos\nRecompensa: Trofeo \'Memoria de oro\' al completar el tablero sin ayuda'),
(6, 2, 2, 'Caza-Consonantes', 'Identificar consonantes sencillas (m, p, l, s) dentro de imágenes y palabras cortas.', 'Mecánica: Clasificar palabras / clasificación por categorías\nCómo se juega: 1) Aparece una tarjeta con imagen y nombre. 2) El niño arrastra la tarjeta hasta la cesta de la consonante inicial correspondiente. 3) La cesta emite una señal visual si la clasificación es correcta.\nAdaptaciones TEA: Máximo 4 categorías simultáneas; pictograma grande de la consonante sobre cada cesta; retroalimentación inmediata por tarjeta.\nNiveles: Fácil (2 consonantes) / Medio (3 consonantes) / Difícil (4 consonantes con distractores fonéticos)\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Cazador de letras\' por cesta completada correctamente'),
(7, 2, 7, 'Constructor de Sílabas', 'Combinar una consonante y una vocal para formar sílabas directas (ma, pa, la, etc.).', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Se presentan dos bloques (consonante y vocal). 2) El niño los arrastra y los junta en la base. 3) Al unirse correctamente, se escucha el sonido de la sílaba y se añade un ladrillo a la torre.\nAdaptaciones TEA: Solo dos piezas por ronda; combinación resaltada con color al acercarse; sin límite de tiempo en nivel fácil.\nNiveles: Fácil (sílabas con m, p, l) / Medio (se suman s, t, n) / Difícil (sílabas inversas y trabadas simples)\nTiempo estimado: 6-9 minutos\nRecompensa: Ladrillo dorado por cada sílaba correctamente formada'),
(8, 2, 3, 'Rompecabezas Silábico', 'Armar una palabra completa uniendo piezas de rompecabezas, cada una con una sílaba.', 'Mecánica: Rompecabezas\nCómo se juega: 1) Se muestran las piezas desordenadas. 2) El niño arrastra cada pieza hasta su lugar. 3) Al encajar todas, se revela la imagen y se lee la palabra en voz alta.\nAdaptaciones TEA: Piezas con bordes de encaje evidente; máximo 3 piezas por palabra; imagen de referencia siempre visible.\nNiveles: Fácil (2 piezas) / Medio (3 piezas) / Difícil (4 piezas con sílabas menos frecuentes)\nTiempo estimado: 6-9 minutos\nRecompensa: Pieza dorada de colección por cada rompecabezas completado'),
(9, 3, 2, 'Une la Palabra', 'Relacionar una palabra escrita con la imagen que representa su significado.', 'Mecánica: Unir palabra con imagen\nCómo se juega: 1) Se presentan palabras e imágenes en dos columnas. 2) El niño traza una línea o toca la palabra y luego la imagen correspondiente. 3) La conexión correcta se resalta en verde suave.\nAdaptaciones TEA: Máximo 4 pares por ronda; tipografía grande y espaciada; sin distractores visuales adicionales.\nNiveles: Fácil (3 pares) / Medio (4 pares) / Difícil (5 pares con palabras visualmente parecidas)\nTiempo estimado: 5-8 minutos\nRecompensa: Cinta de color por cada ronda completada sin errores'),
(10, 3, 4, 'Lector Estrella', 'Leer palabras sencillas en voz alta o de forma guiada, apoyándose en imágenes y en la lectura modelada.', 'Mecánica: Lectura interactiva\nCómo se juega: 1) Aparece la palabra con su imagen. 2) El niño puede tocar \'escuchar\' para oír el modelo de lectura. 3) Toca \'leer\' cuando esté listo y confirma que la leyó. 4) Se enciende una estrella en su constelación.\nAdaptaciones TEA: El estudiante puede escuchar el modelo de lectura antes de intentarlo; sin evaluación de pronunciación estricta, solo acompañamiento.\nNiveles: Fácil (palabras de 2 sílabas con apoyo total) / Medio (palabras de 3 sílabas) / Difícil (palabras sin apoyo sonoro previo)\nTiempo estimado: 6-9 minutos\nRecompensa: Estrella dorada acumulable en la \'constelación lectora\' del estudiante'),
(11, 3, 4, 'Busca la Palabra Correcta', 'Discriminar visualmente una palabra correcta entre otras visualmente parecidas, apoyándose en una imagen.', 'Mecánica: Verdadero o falso\nCómo se juega: 1) Se muestra una imagen. 2) Aparecen 2 o 3 palabras parecidas entre sí. 3) El niño toca la palabra que corresponde a la imagen. 4) Si acierta, la lupa ilumina la palabra correcta; si falla, se resalta la diferencia entre las palabras.\nAdaptaciones TEA: Máximo 2 opciones en nivel fácil; diferencia entre palabras resaltada con color al fallar; sin tiempo límite.\nNiveles: Fácil (2 opciones muy distintas) / Medio (2 opciones parecidas) / Difícil (3 opciones parecidas)\nTiempo estimado: 5-7 minutos\nRecompensa: Lupa dorada de \'Detective de palabras\' por ronda completada sin errores'),
(12, 4, 6, 'Escribo mi Palabra', 'Escribir palabras sencillas apoyándose en una imagen y en el modelo de la palabra completa.', 'Mecánica: Completar frases / dictado con imágenes\nCómo se juega: 1) Aparece la imagen del objeto. 2) El niño elige letras del banco o las escribe en las casillas. 3) Puede activar el modelo de apoyo si lo necesita. 4) Al completar la palabra, se añade al diccionario ilustrado.\nAdaptaciones TEA: Modelo de la palabra visible como apoyo opcional; casillas grandes; sin corrección negativa, solo guía.\nNiveles: Fácil (con modelo completo visible) / Medio (con modelo parcial) / Difícil (sin modelo, solo imagen)\nTiempo estimado: 6-9 minutos\nRecompensa: Sello \'Escritor en progreso\' por cada palabra escrita correctamente'),
(13, 4, 5, 'Mi Primera Oración', 'Construir una oración sencilla de sujeto-verbo-complemento apoyándose en imágenes.', 'Mecánica: Formar oraciones\nCómo se juega: 1) Se presentan los bloques de imagen-palabra. 2) El niño los arrastra a la línea base en el orden que forma una oración con sentido. 3) Al completar, la oración se lee en voz alta y se añade a la historia de Cuentín.\nAdaptaciones TEA: Máximo 3 bloques por oración; orden sugerido con color; opción de escuchar la oración antes de armarla.\nNiveles: Fácil (bloques en orden correcto, solo unir) / Medio (bloques desordenados) / Difícil (elegir bloques entre varias opciones)\nTiempo estimado: 6-9 minutos\nRecompensa: Cinta de \'Escritor de historias\' por cada oración completada'),
(14, 4, 4, 'Cuento Corto, Gran Aventura', 'Comprender un texto narrativo corto acompañado de imágenes, respondiendo preguntas sencillas sobre lo leído.', 'Mecánica: Preguntas de comprensión\nCómo se juega: 1) El niño observa cada viñeta y puede escuchar la narración. 2) Avanza viñeta por viñeta a su ritmo. 3) Al finalizar, responde 2 o 3 preguntas de comprensión con apoyo de imagen. 4) Recibe retroalimentación por cada respuesta.\nAdaptaciones TEA: Cuento con vocabulario sencillo y estructura predecible; posibilidad de repetir la lectura de cada viñeta; preguntas con máximo 2 opciones en nivel fácil.\nNiveles: Fácil (preguntas literales, 2 opciones) / Medio (preguntas literales, 3 opciones) / Difícil (una pregunta inferencial sencilla)\nTiempo estimado: 8-10 minutos\nRecompensa: Insignia \'Aventurero lector\' al terminar el cuento y responder correctamente'),
(15, 5, 2, 'Señales de mi Ciudad', 'Reconocer el significado de señales y símbolos comunes del entorno (tránsito, seguridad, información).', 'Mecánica: Emparejar\nCómo se juega: 1) Aparece una señal (ej. semáforo en rojo). 2) El niño la relaciona con su significado entre varias opciones. 3) Confirmación inmediata con explicación breve.\nAdaptaciones TEA: Máximo 4 señales por ronda; iconos grandes y de alto contraste; significado siempre acompañado de texto corto.\nTiempo estimado: 5-7 minutos\nRecompensa: Insignia \'Guía de la ciudad\' por ronda completa'),
(16, 5, 4, '¿Qué Significa?', 'Identificar la función (informar, prohibir, advertir) de distintos símbolos del entorno.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se muestra un símbolo. 2) El niño elige entre 2-4 opciones cuál es su función. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Empieza con 2 opciones muy distintas; se puede repetir la pregunta las veces que se necesite.\nTiempo estimado: 5-7 minutos\nRecompensa: Estrellas acumulables'),
(17, 5, 7, 'Clasifica las Señales', 'Agrupar señales según su categoría: seguridad, información o prohibición.', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Aparecen 3 canastas rotuladas (seguridad/información/prohibición). 2) El niño arrastra cada señal a su canasta. 3) Señal correcta = la canasta brilla.\nAdaptaciones TEA: Máximo 3 categorías visibles; pictograma grande en cada canasta; sin límite de tiempo.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Clasificador experto\''),
(18, 6, 2, '¿Quién es Quién?', 'Identificar personajes de un cuento y relacionarlos con su descripción.', 'Mecánica: Emparejar\nCómo se juega: 1) Se leen/escuchan descripciones cortas de personajes. 2) El niño relaciona cada descripción con su imagen. 3) Confirmación visual.\nAdaptaciones TEA: Máximo 4 personajes por ronda; descripción disponible en audio repetible.\nTiempo estimado: 5-8 minutos\nRecompensa: Cinta de \'Conocedor de personajes\''),
(19, 6, 4, 'El Escenario del Cuento', 'Reconocer el espacio (lugar) donde ocurre la historia narrada.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se narra un fragmento corto. 2) El niño elige entre varias imágenes cuál es el lugar de la historia. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Imágenes muy diferenciadas entre sí en nivel fácil; audio repetible antes de responder.\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Explorador de escenarios\''),
(20, 6, 7, 'Arma la Escena', 'Combinar personaje, espacio y acción para construir una escena coherente de un cuento.', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Se presentan tres columnas: personajes, espacios, acciones. 2) El niño arrastra un elemento de cada columna a la escena central. 3) Al formar una combinación válida, la escena cobra vida con una animación breve.\nAdaptaciones TEA: Máximo 3 opciones por columna; combinaciones siempre válidas en nivel fácil.\nTiempo estimado: 6-9 minutos\nRecompensa: Medalla \'Director de escena\''),
(21, 7, 4, 'Cuento y Vivencia', 'Comprender un texto literario corto respondiendo preguntas relacionadas con su propia experiencia.', 'Mecánica: Selección múltiple\nCómo se juega: 1) El niño escucha/lee un cuento corto. 2) Responde preguntas de comprensión y de relación con su propia vida. 3) Retroalimentación positiva en cada respuesta.\nAdaptaciones TEA: Cuentos con vocabulario cotidiano y cercano; máximo 2-3 preguntas por cuento.\nTiempo estimado: 8-10 minutos\nRecompensa: Insignia \'Lector reflexivo\''),
(22, 7, 4, '¿Te ha Pasado?', 'Relacionar situaciones de un cuento con experiencias personales, identificando semejanzas y diferencias.', 'Mecánica: Verdadero o falso\nCómo se juega: 1) Se presenta una afirmación sobre el cuento comparada con la vida cotidiana. 2) El niño responde si es verdadera o falsa para él. 3) No hay respuesta \'incorrecta\' en las preguntas de opinión, solo se registra.\nAdaptaciones TEA: Preguntas cortas y directas; sin presión de tiempo.\nTiempo estimado: 5-7 minutos\nRecompensa: Corazón de \'Comparte tu experiencia\''),
(23, 7, 5, 'Ordena la Historia', 'Reconstruir la secuencia de los eventos principales de un cuento corto.', 'Mecánica: Ordenar secuencias\nCómo se juega: 1) Se presentan 3-4 escenas del cuento desordenadas. 2) El niño las arrastra al orden correcto. 3) Al terminar, se reproduce el cuento completo en el orden armado.\nAdaptaciones TEA: Máximo 3 escenas en nivel fácil; imágenes de apoyo siempre visibles.\nTiempo estimado: 6-9 minutos\nRecompensa: Boleto de \'Narrador estrella\''),
(24, 8, 4, '¿De Qué Tratará?', 'Predecir el contenido de un texto a partir de su título e imagen de portada.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se muestra el título e imagen de un texto. 2) El niño elige de qué cree que tratará entre varias opciones. 3) Se revela el texto real para comparar.\nAdaptaciones TEA: Opciones con imágenes claramente distintas; sin penalizar la predicción equivocada.\nTiempo estimado: 5-7 minutos\nRecompensa: Insignia \'Detective de portadas\''),
(25, 8, 2, 'Tipo de Texto', 'Reconocer distintos tipos de texto (cuento, receta, carta, noticia) según su estructura típica.', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta un fragmento de texto. 2) El niño lo relaciona con su tipo (cuento, receta, carta...). 3) Confirmación con explicación breve de las pistas.\nAdaptaciones TEA: Máximo 3 tipos de texto por ronda; fragmentos cortos y con formato visual distintivo.\nTiempo estimado: 6-9 minutos\nRecompensa: Sello \'Coleccionista de textos\''),
(26, 8, 4, 'Adivina el Final', 'Anticipar el posible final de una historia a partir de conocimientos previos y pistas del texto.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se narra una historia hasta un punto clave. 2) El niño elige el final más probable entre varias opciones. 3) Se revela el final real y se compara.\nAdaptaciones TEA: Máximo 2 opciones en nivel fácil; pistas visuales de apoyo.\nTiempo estimado: 6-9 minutos\nRecompensa: Estrella de \'Adivino de historias\''),
(27, 9, 2, 'Texto, Sonido e Imagen', 'Reconocer que una obra puede combinar texto, sonido e imagen, identificando cada elemento.', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta un ejemplo (afiche, video corto, canción). 2) El niño identifica qué elementos lo componen (texto/sonido/imagen). 3) Retroalimentación con ejemplos.\nAdaptaciones TEA: Ejemplos cortos y conocidos; iconos grandes para cada tipo de elemento.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Explorador multimedia\''),
(28, 9, 4, '¿Qué Lenguaje Usa?', 'Identificar si una manifestación artística usa principalmente texto, imagen, sonido o una combinación.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se muestra un ejemplo breve. 2) El niño elige qué lenguaje(s) usa. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Ejemplos con un solo lenguaje predominante en nivel fácil.\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Crítico de arte junior\''),
(29, 9, 7, 'Arma el Afiche', 'Combinar texto, imagen y sonido para construir una pieza comunicativa sencilla.', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Se presenta un afiche vacío y piezas (título, imagen, ícono de sonido). 2) El niño arrastra cada pieza a su lugar. 3) Al completarlo, el afiche se anima.\nAdaptaciones TEA: Máximo 3 piezas por afiche; casillas grandes y claramente marcadas.\nTiempo estimado: 6-9 minutos\nRecompensa: Medalla \'Creador multimedia\''),
(30, 10, 4, '¿Quién Cuenta la Historia?', 'Identificar al narrador de un texto narrativo y distinguirlo de los personajes.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se lee un fragmento narrado. 2) El niño identifica quién narra la historia. 3) Retroalimentación con explicación.\nAdaptaciones TEA: Fragmentos cortos con un narrador claramente identificable.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Detective del narrador\''),
(31, 10, 5, 'Inicio, Nudo y Desenlace', 'Reconocer la estructura narrativa básica (inicio, nudo, desenlace) de un cuento.', 'Mecánica: Ordenar secuencias\nCómo se juega: 1) Se presentan 3 fragmentos del cuento. 2) El niño los ordena según la estructura narrativa. 3) Se revela el cuento completo ordenado.\nAdaptaciones TEA: Máximo 3 fragmentos; imagen de apoyo para cada parte.\nTiempo estimado: 6-9 minutos\nRecompensa: Boleto de \'Estructura perfecta\''),
(32, 10, 3, 'El Detective del Cuento', 'Reconstruir visualmente los elementos de la estructura narrativa de una historia.', 'Mecánica: Rompecabezas\nCómo se juega: 1) Se presentan piezas con el inicio, nudo y desenlace desordenados. 2) El niño arma el rompecabezas en el orden correcto. 3) Al completarlo, se revela la historia.\nAdaptaciones TEA: Máximo 3 piezas; bordes de encaje evidente.\nTiempo estimado: 6-9 minutos\nRecompensa: Pieza dorada de colección'),
(33, 11, 2, '¿Quién Habla y Quién Escucha?', 'Identificar el emisor y el receptor en una situación comunicativa específica.', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta una situación (ej. una carta, una llamada). 2) El niño identifica quién es el emisor y quién el receptor. 3) Confirmación con explicación.\nAdaptaciones TEA: Situaciones cotidianas y conocidas; máximo 2 roles por ronda.\nTiempo estimado: 5-8 minutos\nRecompensa: Insignia \'Comunicador claro\''),
(34, 11, 4, '¿Para Qué lo Dice?', 'Reconocer el propósito comunicativo (informar, pedir, agradecer, invitar) de un mensaje.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se presenta un mensaje corto. 2) El niño elige su propósito comunicativo. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Mensajes cortos con un propósito claramente predominante.\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Propósito claro\''),
(35, 11, 5, 'Arma la Conversación', 'Ordenar los turnos de una conversación corta respetando la secuencia comunicativa.', 'Mecánica: Ordenar secuencias\nCómo se juega: 1) Se presentan 3-4 turnos de diálogo desordenados. 2) El niño los ordena. 3) Se reproduce la conversación completa.\nAdaptaciones TEA: Máximo 3 turnos en nivel fácil; íconos de emisor/receptor visibles.\nTiempo estimado: 6-9 minutos\nRecompensa: Cinta de \'Buen conversador\''),
(36, 12, 4, 'Lectura entre Líneas', 'Responder preguntas inferenciales sobre un texto, deduciendo información que no está escrita literalmente.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se lee un texto corto. 2) El niño responde preguntas que requieren deducir, no solo recordar. 3) Retroalimentación con la pista del texto que ayuda a inferir.\nAdaptaciones TEA: Preguntas inferenciales sencillas en nivel fácil, con una pista visual de apoyo.\nTiempo estimado: 8-10 minutos\nRecompensa: Insignia \'Lector entre líneas\''),
(37, 12, 4, '¿Qué Opinas?', 'Responder preguntas críticas sobre un texto, justificando una postura sencilla.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se presenta una situación del texto. 2) El niño elige la opción que mejor representa su opinión razonada. 3) Se muestra una reflexión breve sobre la respuesta.\nAdaptaciones TEA: Sin respuesta única \'correcta\' en preguntas de opinión; se valora la justificación, no penaliza.\nTiempo estimado: 6-9 minutos\nRecompensa: Sello \'Pensador crítico\''),
(38, 12, 6, 'Completa la Idea', 'Completar una conclusión o idea inferida a partir de la información de un texto.', 'Mecánica: Completar frases\nCómo se juega: 1) Se presenta un texto corto y una frase incompleta con la conclusión. 2) El niño elige o escribe la palabra que completa la idea. 3) Retroalimentación con la explicación de la inferencia.\nAdaptaciones TEA: Banco de palabras disponible como apoyo; sin corrección negativa.\nTiempo estimado: 6-9 minutos\nRecompensa: Sello \'Constructor de ideas\''),
(39, 13, 2, 'Mis Cinco Sentidos', 'Relacionar cada sentido con la característica del entorno que permite percibir.', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta un sentido (ej. oído). 2) El niño lo relaciona con lo que permite percibir (sonidos). 3) Confirmación con ejemplo visual.\nAdaptaciones TEA: Máximo 3 sentidos por ronda; pictogramas grandes y claros.\nTiempo estimado: 5-8 minutos\nRecompensa: Insignia \'Explorador sensorial\''),
(40, 13, 4, 'Caliente o Frío', 'Clasificar objetos según la característica que se percibe con los sentidos (temperatura, textura, sabor).', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se muestra un objeto. 2) El niño elige la característica que mejor lo describe. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Objetos cotidianos y conocidos; máximo 2 opciones en nivel fácil.\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Detective de los sentidos\''),
(41, 13, 7, 'El Detective de Texturas', 'Clasificar objetos según su textura (suave/áspero) usando el sentido del tacto como referencia.', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Aparecen dos canastas: suave y áspero. 2) El niño arrastra cada objeto a la canasta correspondiente. 3) Confirmación visual al acertar.\nAdaptaciones TEA: Máximo 2 categorías; imágenes grandes y contrastantes.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Manos expertas\''),
(42, 14, 2, '¿De Qué Está Hecho?', 'Relacionar objetos cotidianos con el material del que están hechos.', 'Mecánica: Emparejar\nCómo se juega: 1) Se muestra un objeto (ej. una silla de madera). 2) El niño lo relaciona con su material. 3) Confirmación con explicación breve.\nAdaptaciones TEA: Máximo 4 materiales por ronda; objetos muy conocidos.\nTiempo estimado: 5-8 minutos\nRecompensa: Sello \'Conocedor de materiales\''),
(43, 14, 4, 'Fuerte o Flexible', 'Reconocer características de los materiales (dureza, flexibilidad, color, textura) para distintos usos.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se presenta un material. 2) El niño elige cuál es su característica principal. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Comparaciones muy contrastantes en nivel fácil (ej. piedra vs. esponja).\nTiempo estimado: 5-7 minutos\nRecompensa: Insignia \'Científico de materiales\''),
(44, 14, 7, 'Construye con Materiales', 'Relacionar un material con el uso más adecuado según sus características.', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Se presenta un uso (ej. hacer una ventana). 2) El niño arrastra el material más adecuado (ej. vidrio). 3) Confirmación con breve explicación.\nAdaptaciones TEA: Máximo 3 opciones de material por ronda; imágenes claras de cada uso.\nTiempo estimado: 6-9 minutos\nRecompensa: Medalla \'Constructor experto\''),
(45, 15, 4, '¿Vivo o No Vivo?', 'Diferenciar seres vivos de objetos inertes reconociendo características comunes de los seres vivos.', 'Mecánica: Verdadero o falso\nCómo se juega: 1) Se muestra una imagen. 2) El niño indica si es un ser vivo o no. 3) Retroalimentación con la característica clave (se alimenta, respira, crece...).\nAdaptaciones TEA: Ejemplos muy contrastantes en nivel fácil (planta vs. piedra).\nTiempo estimado: 5-7 minutos\nRecompensa: Insignia \'Guardián de la vida\''),
(46, 15, 2, 'Características de los Seres Vivos', 'Relacionar cada característica común de los seres vivos (se alimenta, respira, crece, responde) con un ejemplo.', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta una característica. 2) El niño la relaciona con la imagen de un ser vivo que la representa. 3) Confirmación visual.\nAdaptaciones TEA: Máximo 3 características por ronda; pictogramas grandes.\nTiempo estimado: 6-9 minutos\nRecompensa: Sello \'Biólogo junior\''),
(47, 15, 7, 'Clasifica: Planta, Animal u Objeto', 'Clasificar elementos del entorno en plantas, animales u objetos inertes.', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Aparecen tres canastas: planta, animal, objeto. 2) El niño arrastra cada elemento a su canasta. 3) Confirmación visual al acertar.\nAdaptaciones TEA: Máximo 3 categorías; imágenes muy diferenciadas.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Clasificador de la naturaleza\''),
(48, 16, 5, 'Yo Antes y Ahora', 'Reconocer los cambios del cuerpo a lo largo del tiempo, ordenando etapas de crecimiento.', 'Mecánica: Ordenar secuencias\nCómo se juega: 1) Se presentan imágenes de distintas etapas (bebé, niño, adulto). 2) El niño las ordena cronológicamente. 3) Confirmación visual al completar la secuencia.\nAdaptaciones TEA: Máximo 3 etapas; imágenes de apoyo siempre visibles.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Línea de tiempo\''),
(49, 16, 2, '¿A Quién Me Parezco?', 'Reconocer semejanzas y diferencias físicas entre un niño y sus padres.', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta una característica física. 2) El niño la relaciona con quién la comparte (mamá, papá). 3) Confirmación con explicación breve.\nAdaptaciones TEA: Ejemplos sencillos y visuales (color de ojos, altura); sin juicios de valor.\nTiempo estimado: 5-8 minutos\nRecompensa: Sello \'Familia y semejanzas\''),
(50, 16, 4, 'Cambios en mi Cuerpo', 'Identificar cambios físicos que experimenta el cuerpo con el paso del tiempo.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se presenta una imagen de un cambio corporal (ej. crecer los dientes). 2) El niño identifica de qué cambio se trata. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Ejemplos cotidianos y conocidos por el niño.\nTiempo estimado: 5-7 minutos\nRecompensa: Insignia \'Yo crezco\''),
(51, 17, 4, 'Empuja y Jala', 'Identificar si una acción mecánica sobre un objeto es un empuje o un jalón (tipos de fuerza).', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se muestra una acción (ej. abrir un cajón). 2) El niño identifica si es empujar o jalar. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Ejemplos cotidianos con imágenes claras de la dirección del movimiento.\nTiempo estimado: 5-7 minutos\nRecompensa: Insignia \'Físico junior\''),
(52, 17, 2, '¿Se Dobla o Se Rompe?', 'Relacionar un material con la forma en que reacciona ante una fuerza (se dobla, se rompe, resiste).', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta un material sometido a fuerza. 2) El niño lo relaciona con su reacción. 3) Confirmación con explicación breve.\nAdaptaciones TEA: Ejemplos muy contrastantes en nivel fácil (goma vs. vidrio).\nTiempo estimado: 6-9 minutos\nRecompensa: Sello \'Explorador de materiales\''),
(53, 17, 7, 'Pon a Prueba los Materiales', 'Clasificar materiales según su resistencia a la fuerza (flexible, rígido, quebradizo).', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Aparecen canastas por tipo de resistencia. 2) El niño arrastra cada material a su categoría. 3) Confirmación visual.\nAdaptaciones TEA: Máximo 3 categorías; ejemplos conocidos del aula.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Laboratorio de materiales\''),
(54, 18, 7, 'Sólido, Líquido o Gas', 'Clasificar sustancias cotidianas según su estado (sólido, líquido, gaseoso).', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Aparecen tres canastas: sólido, líquido, gas. 2) El niño arrastra cada sustancia a su estado. 3) Confirmación visual al acertar.\nAdaptaciones TEA: Máximo 3 categorías; ejemplos muy conocidos (agua, aire, piedra).\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Científico de estados\''),
(55, 18, 4, '¿Qué Estado Es?', 'Reconocer el estado de la materia (sólido, líquido, gaseoso) de una sustancia mostrada.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se muestra una sustancia. 2) El niño elige su estado. 3) Retroalimentación inmediata con explicación breve.\nAdaptaciones TEA: Ejemplos con imagen y sin ambigüedad en nivel fácil.\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Detective de estados\''),
(56, 18, 5, 'El Ciclo del Agua', 'Reconocer la secuencia de cambios de estado del agua en su ciclo natural.', 'Mecánica: Ordenar secuencias\nCómo se juega: 1) Se presentan imágenes del ciclo del agua desordenadas. 2) El niño las ordena. 3) Se anima el ciclo completo al terminar.\nAdaptaciones TEA: Máximo 3-4 pasos; imágenes de apoyo siempre visibles.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Guardián del agua\''),
(57, 19, 2, '¿Dónde Vivo?', 'Relacionar una planta o animal con el ambiente donde vive según sus necesidades básicas.', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta un ser vivo. 2) El niño lo relaciona con su hábitat. 3) Confirmación con explicación breve.\nAdaptaciones TEA: Máximo 3 hábitats por ronda; imágenes grandes y reconocibles.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Explorador de hábitats\''),
(58, 19, 4, 'Lo Que Necesito para Vivir', 'Reconocer las necesidades básicas (luz, agua, aire, suelo) de plantas y animales.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se presenta un ser vivo. 2) El niño elige qué necesita para vivir. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Ejemplos cotidianos; máximo 2-3 opciones en nivel fácil.\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Cuidador de la naturaleza\''),
(59, 19, 7, 'Arma el Hábitat', 'Construir un hábitat adecuado combinando los elementos que un ser vivo necesita para sobrevivir.', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Se presenta un ser vivo y un espacio vacío. 2) El niño arrastra los elementos que necesita (agua, luz, alimento). 3) Al completar el hábitat, el ser vivo \'se instala\' con una animación.\nAdaptaciones TEA: Máximo 3 elementos por hábitat; imágenes de apoyo siempre visibles.\nTiempo estimado: 6-9 minutos\nRecompensa: Medalla \'Constructor de hábitats\''),
(60, 20, 5, 'El Ciclo de Vida', 'Reconocer la secuencia de cambios físicos en el ciclo de vida de una planta o animal.', 'Mecánica: Ordenar secuencias\nCómo se juega: 1) Se presentan las etapas del ciclo de vida desordenadas (ej. semilla, planta pequeña, planta adulta). 2) El niño las ordena. 3) Se anima el ciclo completo.\nAdaptaciones TEA: Máximo 3-4 etapas; imágenes de apoyo siempre visibles.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Guardián del ciclo de vida\''),
(61, 20, 4, '¿Qué Cambió?', 'Identificar el cambio físico ocurrido entre dos etapas del ciclo de vida de un ser vivo.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se muestran dos imágenes de etapas distintas. 2) El niño identifica qué cambió. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Comparaciones muy visibles en nivel fácil (huevo vs. pollito).\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Observador de cambios\''),
(62, 20, 3, 'Rompecabezas del Ciclo', 'Reconstruir visualmente las etapas del ciclo de vida de una planta o animal.', 'Mecánica: Rompecabezas\nCómo se juega: 1) Se presentan piezas con las etapas del ciclo desordenadas. 2) El niño arma el rompecabezas en el orden correcto. 3) Al completarlo, se revela el ciclo completo.\nAdaptaciones TEA: Máximo 4 piezas; bordes de encaje evidente.\nTiempo estimado: 6-9 minutos\nRecompensa: Pieza dorada de colección'),
(63, 21, 2, 'Deja Pasar la Luz', 'Relacionar un material con su comportamiento frente a la luz (opaco, transparente, translúcido, reflectivo).', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta un material (ej. espejo, vidrio, cartón). 2) El niño lo relaciona con su comportamiento ante la luz. 3) Confirmación con explicación breve.\nAdaptaciones TEA: Máximo 3 categorías por ronda; ejemplos muy conocidos del aula.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Explorador de la luz\''),
(64, 21, 4, '¿Refleja o Absorbe?', 'Reconocer si un material refleja, absorbe o deja pasar la luz.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se presenta un objeto. 2) El niño elige qué le pasa a la luz al chocar con él. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Ejemplos con imagen clara y contraste alto en nivel fácil.\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Científico de la luz\''),
(65, 21, 7, 'Clasifica los Materiales', 'Clasificar materiales según cómo se comportan frente a la luz (opaco, transparente, translúcido).', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Aparecen tres canastas por tipo de material. 2) El niño arrastra cada objeto a su categoría. 3) Confirmación visual al acertar.\nAdaptaciones TEA: Máximo 3 categorías; imágenes conocidas del entorno escolar.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Laboratorio de la luz\''),
(66, 22, 4, 'Grande o Pequeña', 'Predecir si una sombra será grande o pequeña según la distancia entre la luz, el objeto y la superficie.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se muestra una escena con luz, objeto y superficie a cierta distancia. 2) El niño predice el tamaño de la sombra. 3) Se revela el resultado para comparar.\nAdaptaciones TEA: Comparaciones muy contrastantes en nivel fácil (muy cerca vs. muy lejos).\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Detective de sombras\''),
(67, 22, 5, 'Arma la Escena de Sombra', 'Reconocer el orden correcto de los elementos que producen una sombra: fuente de luz, objeto y superficie.', 'Mecánica: Ordenar secuencias\nCómo se juega: 1) Se presentan los tres elementos desordenados. 2) El niño los ordena de forma correcta. 3) Se anima la formación de la sombra.\nAdaptaciones TEA: Solo 3 elementos; imágenes de apoyo siempre visibles.\nTiempo estimado: 6-9 minutos\nRecompensa: Sello \'Arquitecto de sombras\''),
(68, 22, 4, '¿Qué Pasa con la Sombra?', 'Reconocer cómo cambia una sombra al modificar la distancia entre la fuente de luz y el objeto.', 'Mecánica: Verdadero o falso\nCómo se juega: 1) Se presenta una afirmación sobre el cambio de una sombra. 2) El niño responde si es verdadera o falsa. 3) Retroalimentación con explicación breve.\nAdaptaciones TEA: Afirmaciones cortas y directas; ejemplo visual de apoyo siempre disponible.\nTiempo estimado: 5-7 minutos\nRecompensa: Insignia \'Físico de la luz\''),
(69, 23, 2, 'Sonidos que Vibran', 'Relacionar una fuente de sonido con la vibración que lo produce.', 'Mecánica: Emparejar\nCómo se juega: 1) Se presenta una fuente de sonido (ej. una guitarra). 2) El niño la relaciona con la parte que vibra para producir el sonido. 3) Confirmación con explicación breve.\nAdaptaciones TEA: Máximo 3 fuentes por ronda; apoyo de audio si es posible.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Explorador del sonido\''),
(70, 23, 4, 'Agudo o Grave', 'Clasificar sonidos según su altura (agudo o grave).', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se describe o reproduce un sonido. 2) El niño identifica si es agudo o grave. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Ejemplos muy contrastantes en nivel fácil (pito vs. tambor grande).\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Oído musical\''),
(71, 23, 7, '¿Por Dónde Viaja el Sonido?', 'Clasificar medios (sólido, líquido, gaseoso) según su capacidad de propagar el sonido.', 'Mecánica: Arrastrar y soltar\nCómo se juega: 1) Aparecen tres canastas por tipo de medio. 2) El niño arrastra ejemplos (agua, aire, madera) a su categoría. 3) Confirmación visual.\nAdaptaciones TEA: Máximo 3 categorías; ejemplos cotidianos del entorno.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Científico del sonido\''),
(72, 24, 5, 'El Agua Cambia', 'Reconocer la secuencia de cambios de estado del agua según la temperatura (hielo, agua, vapor).', 'Mecánica: Ordenar secuencias\nCómo se juega: 1) Se presentan las tres formas del agua desordenadas. 2) El niño las ordena de menor a mayor temperatura. 3) Se anima la transformación completa.\nAdaptaciones TEA: Solo 3 pasos; imágenes de apoyo siempre visibles.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Guardián del agua\''),
(73, 24, 4, 'Sube o Baja la Temperatura', 'Reconocer si un cambio de estado del agua ocurre al subir o bajar la temperatura.', 'Mecánica: Selección múltiple\nCómo se juega: 1) Se presenta un cambio de estado (ej. agua a hielo). 2) El niño identifica si la temperatura sube o baja. 3) Retroalimentación inmediata.\nAdaptaciones TEA: Ejemplos muy conocidos (congelar, hervir); máximo 2 opciones en nivel fácil.\nTiempo estimado: 5-7 minutos\nRecompensa: Sello \'Termómetro experto\''),
(74, 24, 6, 'Experimento del Agua', 'Completar la conclusión de un pequeño experimento sobre los cambios de estado del agua.', 'Mecánica: Completar frases\nCómo se juega: 1) Se describe un experimento sencillo (ej. hielo al sol). 2) El niño completa la frase que explica qué pasó. 3) Retroalimentación con la explicación completa.\nAdaptaciones TEA: Banco de palabras disponible como apoyo; sin corrección negativa.\nTiempo estimado: 6-9 minutos\nRecompensa: Insignia \'Científico experimental\'');

