(43, 35, '{\"rondas\":[{\"instruccion\":\"Ordena los turnos de la conversación\",\"orden_correcto\":[\"saludo\",\"pregunta\",\"respuesta\"],\"piezas\":[{\"id\":\"saludo\",\"emoji\":\"👋\",\"etiqueta\":\"¡Hola!\"},{\"id\":\"pregunta\",\"emoji\":\"❓\",\"etiqueta\":\"¿Cómo estás?\"},{\"id\":\"respuesta\",\"emoji\":\"😊\",\"etiqueta\":\"Muy bien, ¿y tú?\"}]},{\"instruccion\":\"Ordena los turnos de la conversacion\",\"orden_correcto\":[\"a\",\"b\",\"c\"],\"piezas\":[{\"id\":\"a\",\"emoji\":\"🙋\",\"etiqueta\":\"Buenos dias, senora\"},{\"id\":\"b\",\"emoji\":\"❓\",\"etiqueta\":\"Tiene pan fresco?\"},{\"id\":\"c\",\"emoji\":\"🥖\",\"etiqueta\":\"Si, acabo de hornearlo\"}]},{\"instruccion\":\"Ordena los turnos de la conversacion\",\"orden_correcto\":[\"a\",\"b\",\"c\"],\"piezas\":[{\"id\":\"a\",\"emoji\":\"📞\",\"etiqueta\":\"Hola, con quien hablo?\"},{\"id\":\"b\",\"emoji\":\"🗣️\",\"etiqueta\":\"Soy Ana, esta Luis?\"},{\"id\":\"c\",\"emoji\":\"👦\",\"etiqueta\":\"Si, ya te lo paso\"}]},{\"instruccion\":\"Ordena los turnos de la conversacion\",\"orden_correcto\":[\"a\",\"b\",\"c\"],\"piezas\":[{\"id\":\"a\",\"emoji\":\"👋\",\"etiqueta\":\"Hola, como te llamas?\"},{\"id\":\"b\",\"emoji\":\"😊\",\"etiqueta\":\"Me llamo Sofia\"},{\"id\":\"c\",\"emoji\":\"🤝\",\"etiqueta\":\"Mucho gusto, Sofia\"}]},{\"instruccion\":\"Ordena los turnos de la conversacion\",\"orden_correcto\":[\"a\",\"b\",\"c\"],\"piezas\":[{\"id\":\"a\",\"emoji\":\"🙇\",\"etiqueta\":\"Disculpe, que hora es?\"},{\"id\":\"b\",\"emoji\":\"⏰\",\"etiqueta\":\"Son las tres\"},{\"id\":\"c\",\"emoji\":\"🙏\",\"etiqueta\":\"Gracias\"}]},{\"instruccion\":\"Ordena los turnos de la conversacion\",\"orden_correcto\":[\"a\",\"b\",\"c\"],\"piezas\":[{\"id\":\"a\",\"emoji\":\"🚪\",\"etiqueta\":\"Toc toc, se puede?\"},{\"id\":\"b\",\"emoji\":\"✅\",\"etiqueta\":\"Claro, sigue\"},{\"id\":\"c\",\"emoji\":\"😀\",\"etiqueta\":\"Gracias, vengo por mi cuaderno\"}]},{\"instruccion\":\"Ordena los turnos de la conversación\",\"orden_correcto\":[\"a\",